import{_ as i,o as a,c as n,a4 as l}from"./chunks/framework.B-wJupoK.js";const c=JSON.parse('{"title":"54-Iterable 和 Collections","description":"","frontmatter":{},"headers":[],"relativePath":"仓颉入门到实战/54-Iterable 和 Collections/54-Iterable 和 Collections.md","filePath":"仓颉入门到实战/54-Iterable 和 Collections/54-Iterable 和 Collections.md","lastUpdated":1741103168000,"__rawMarkdown":"# 54-Iterable 和 Collections\\n\\n## Iterable 和 Collections\\n\\n前面已经了解过 Range、Array、ArrayList，它们都可以使用 for-in 进行遍历操作，那么对一个用户自定义类型，能不能实现类似的遍历操作呢？答案是可以的。\\n\\nRange、Array、ArrayList 其实都是通过 Iterable 来支持 for-in 语法的。\\n\\nIterable 是如下形式（只展示了核心代码）的一个内置 interface。\\n\\n```javascript\\ninterface Iterable<T> {\\n    func iterator(): Iterator<T>\\n    ...\\n}\\n```\\n\\niterator 函数要求返回的 Iterator 类型是如下形式（只展示了核心代码）的另一个内置 interface。\\n\\n```javascript\\ninterface Iterator<T> <: Iterable<T> {\\n    mut func next(): Option<T>\\n    ...\\n}\\n```\\n\\n可以使用 for-in 语法来遍历任何一个实现了 Iterable 接口类型的实例。\\n\\n假设有这样一个 for-in 代码。\\n\\n```javascript\\nlet list = [1, 2, 3]\\nfor (i in list) {\\n    println(i)\\n}\\n```\\n\\n那么它等价于如下形式的 while 代码。\\n\\n```javascript\\nlet list = [1, 2, 3]\\nvar it = list.iterator()\\nwhile (true) {\\n    match (it.next()) {\\n        case Some(i) => println(i)\\n        case None => break\\n    }\\n}\\n```\\n\\n另外一种常见的遍历 Iterable 类型的方法是使用 while-let，比如上面 while 代码的另一种等价写法是：\\n\\n```javascript\\nlet list = [1, 2, 3]\\nvar it = list.iterator()\\nwhile (let Some(i) <- it.next()) {\\n    println(i)\\n}\\n```\\n\\nArray、ArrayList、HashSet、HashMap 类型都实现了 Iterable，因此都可以将其用在 for-in 或者 while-let 中。"}'),t={name:"仓颉入门到实战/54-Iterable 和 Collections/54-Iterable 和 Collections.md"};function e(p,s,h,r,k,E){return a(),n("div",null,[...s[0]||(s[0]=[l("",16)])])}const g=i(t,[["render",e]]);export{c as __pageData,g as default};
